INSERT INTO `kegiatan` (`id`, `kode_kegiatan`, `judul`, `status`, `status_verifikasi`, `location_id`, `tanggal_mulai`, `tanggal_selesai`, `penyelenggara`, `skala_kegiatan`, `deskripsi`, `rencana_output`, `deskripsi_hasil`, `jumlah_peserta`, `foto_utama`, `dibuat_oleh`, `diverifikasi_oleh`, `catatan_verifikasi`, `verified_at`, `created_at`, `updated_at`) VALUES
(2, 'KEG-2026-002', 'Seminar Penyatuan Pertanian Bogor Raya', 'selesai', 'approved', 2, '2026-07-17', '2026-07-19', 'IPB University', 'Kota/Kabupaten', NULL, NULL, NULL, 100, 'uploads/kegiatan/kegiatan_2_6a60755042fa3.jpg', NULL, NULL, NULL, '2026-07-17 13:52:13', '2026-07-17 06:52:13', '2026-08-04 03:53:55'),
(42, 'KEG-2026-003', 'Contoh Seminar Perikanan', 'selesai', 'approved', 2, '2026-07-20', '2026-07-23', 'Sekolah Vokasi IPB', 'Kota/Kabupaten', 'ldsmldjmsada - ikan', NULL, 'Responden mengikuti acara dengan baik dan dapat memahami gambaran dengan hikmat', 60, 'uploads/kegiatan/kegiatan_42_6a5d85e656fbf.jpg', NULL, NULL, NULL, '2026-07-20 09:20:22', '2026-07-20 02:20:22', '2026-08-04 03:53:55'),
(43, 'KEG-2026-004', 'Pelatihan IoT untuk Pertanian Presisi', 'selesai', 'approved', 1, '2026-07-28', '2026-07-31', 'SEAMEO BIOTROP', 'Kota/Kabupaten', 'Kegiatan ini adalah wadah untuk kemajuan teknologi di bidang pertanian', NULL, 'Mantap', 50, 'uploads/kegiatan/kegiatan_43_6a670530717d3.jpg', NULL, NULL, NULL, '2026-07-27 13:43:16', '2026-07-27 06:43:16', '2026-08-10 02:33:30'),
(44, 'KEG-2026-005', 'Seminar Hasil Olahan Minyak Kayu Putih Sebagai Minuman Herbal', 'selesai', 'approved', 8, '2026-07-30', '2026-07-31', 'IPB University', 'Kota/Kabupaten', 'Seminar Hasil Olahan Minyak Kayu Putih Sebagai Minuman Herbal adalah kegiatan yang dilakukan untuk menghilangkan persepsi bahwa minyak kayu putih tidak bisa digunakan sebagai minuman', 'Peserta dapat memahami manfaat minyak kayu putih sebagai minuman herbal', 'Responden dapat bereksperimen dengan hasil olahan minyak kayu putih dengan baik', NULL, 'uploads/kegiatan/revisi_44_6a7a7eb4ad004.jpg', NULL, NULL, NULL, '2026-07-29 11:29:14', '2026-07-29 04:29:14', '2026-08-11 01:46:06'),
(45, 'KEG-2026-006', 'Seminar Refleksi Masa Depan Pembangunan dan Pendidikan Pertanian Indonesia', 'selesai', 'approved', 8, '2026-08-05', '2026-08-07', 'Institut Pertanian Bogor', 'Kota/Kabupaten', 'Seminar dengan moderator Prof Dr Syafrida Manuwoto ini juga menghadirkan pembicara Dekan Fakultas Pertanian IPB Dr Ernan Rustiadi yang menyampaikan makalah bertajuk ‘Masa Depan Pembangunan Pertanian Indonesia’, dan  Dr Robert Manurung, dari Sekolah Ilmu dan Teknologi Hayati, Institut Teknologi Bandung. Dengan judul makalah ‘Menyongsong Era Pertanian Industrial dan Industrialisasi Perdesaan’.', NULL, 'Seminar berjalan dengan baik dan kondusif', 60, 'uploads/kegiatan/kegiatan_45_6a72955f15c65.jpg', 1, 10, NULL, '2026-08-05 08:53:39', '2026-08-05 01:43:59', '2026-08-10 02:34:09'),
(46, 'KEG-2026-007', 'Pelatihan Nasional dan Seminar Regional Pengelolaan Lahan Suboptimal', 'selesai', 'approved', 10, '2026-08-05', '2026-08-10', 'SEAMEO BIOTROP,', 'Nasional', 'SEAMEO BIOTROP, menggelar Pelatihan Nasional dan Seminar Regional tentang Pengelolaan dan Pemanfaatan Lahan Suboptimal di Universitas Bengkulu selama empat hari, Selasa hingga Jumat (19–22 Mei 2026). Kegiatan ini menjadi langkah strategis dalam memperkuat kolaborasi pendidikan, riset, dan pengembangan pertanian berkelanjutan di Indonesia dan kawasan Asia Tenggara.', 'Para peserta mendapatkan pembekalan dari akademisi dan peneliti berkompeten', 'Sudah mantap', 30, 'uploads/kegiatan/kegiatan_46_6a72dcf49ea8c.jpg', 1, 10, 'Sudah ok', '2026-08-05 13:54:51', '2026-08-05 06:49:24', '2026-08-11 01:32:18'),
(47, 'KEG-2026-008', 'Pelatihan Bangun Pertanian Perkotaan Berbasis Sekolah', 'selesai', 'approved', 6, '2026-08-10', '2026-08-13', 'SEAMEO BIOTROP', 'Kota/Kabupaten', 'Kegiatan ini merupakan bagian dari program nasional yang bertujuan mendukung ketahanan pangan berbasis sekolah serta membangun kapasitas komunitas pendidikan dalam pengelolaan lahan sempit secara produktif dan berkelanjutan.', 'Terbentuk jaringan pendidik dan sekolah pelopor urban farming yang mampu menjadi agen perubahan dalam menciptakan ekosistem ketahanan pangan berkelanjutan berbasis komunitas pendidikan, sejalan dengan tujuan pembangunan berkelanjutan (SDGs)', 'Berjalan dengan baik, perwakilan sekolah-sekolah dapat memahami materi dengan baik dan diharapkan dapat menerapkannya di sekolah masing-masing', 31, 'uploads/kegiatan/kegiatan_47_6a72e29a99f3c.jpg', 1, 10, NULL, '2026-08-10 08:32:22', '2026-08-05 07:13:30', '2026-08-19 03:08:25'),
(48, 'KEG-2025-001', 'Workshop Konservasi Keanekaragaman Hayati Hutan Tropis', 'selesai', 'approved', 11, '2025-09-15', '2025-09-17', 'SEAMEO BIOTROP', 'Nasional', 'Workshop ini membahas strategi konservasi flora dan fauna endemik di kawasan hutan tropis Indonesia, melibatkan peneliti dan mahasiswa kehutanan.', 'Peserta memahami metode inventarisasi keanekaragaman hayati', 'Peserta berhasil menyusun rencana aksi konservasi untuk tiga kawasan percontohan', 45, 'uploads/kegiatan/kegiatan_2_6a60755042fa3.jpg', 1, 10, NULL, '2025-09-15 09:00:00', '2025-09-13 04:00:00', '2025-09-17 07:00:00'),
(49, 'KEG-2025-002', 'Pelatihan Budidaya Ikan Lele Sistem Bioflok', 'selesai', 'approved', 16, '2025-10-05', '2025-10-07', 'Politeknik Pertanian Negeri Sukabumi', 'Kota/Kabupaten', 'Pelatihan teknis budidaya lele dengan sistem bioflok untuk meningkatkan produktivitas kolam terbatas bagi kelompok pembudidaya ikan.', NULL, 'Kelompok tani ikan mampu menerapkan sistem bioflok secara mandiri', 38, 'uploads/kegiatan/kegiatan_42_6a5d85e656fbf.jpg', 1, 10, NULL, '2025-10-05 08:30:00', '2025-10-03 03:00:00', '2025-10-07 06:30:00'),
(50, 'KEG-2025-003', 'Seminar Internasional Perubahan Iklim dan Ketahanan Pangan', 'selesai', 'approved', 17, '2025-11-20', '2025-11-22', 'SEAMEO BIOTROP', 'Internasional', 'Seminar internasional yang menghadirkan pakar dari negara-negara ASEAN untuk membahas dampak perubahan iklim terhadap ketahanan pangan regional.', 'Terbentuknya rekomendasi kebijakan lintas negara ASEAN', 'Seminar menghasilkan deklarasi bersama untuk kolaborasi riset ketahanan pangan', 120, 'uploads/kegiatan/kegiatan_45_6a72955f15c65.jpg', 1, 10, NULL, '2025-11-20 09:00:00', '2025-11-18 03:00:00', '2025-11-22 07:00:00'),
(51, 'KEG-2025-004', 'Pelatihan Pengelolaan Sampah Organik Perkotaan', 'selesai', 'approved', 13, '2025-12-08', '2025-12-10', 'Pemerintah Kota Bogor', 'Kota/Kabupaten', 'Pelatihan pengolahan sampah organik rumah tangga menjadi kompos dan pupuk cair bagi warga perkotaan.', 'Warga mampu mengelola sampah organik mandiri di lingkungan masing-masing', 'Terbentuk bank sampah organik percontohan di tingkat kelurahan', 55, 'uploads/kegiatan/kegiatan_43_6a6705307275b.jpg', 9, 10, NULL, '2025-12-08 08:00:00', '2025-12-06 03:00:00', '2025-12-10 06:00:00'),
(52, 'KEG-2026-009', 'Workshop Pemetaan Partisipatif Berbasis GIS untuk Desa', 'selesai', 'approved', 18, '2026-01-14', '2026-01-16', 'Universitas Gadjah Mada', 'Nasional', 'Workshop pelatihan penggunaan GIS untuk pemetaan partisipatif batas dan potensi desa bersama aparat desa dan mahasiswa.', 'Peserta mampu membuat peta desa berbasis data spasial', 'Dihasilkan sepuluh peta desa percontohan yang siap dipakai untuk perencanaan wilayah', 40, 'uploads/kegiatan/kegiatan_43_6a67075642648.jpg', 1, 10, NULL, '2026-01-14 08:30:00', '2026-01-12 03:00:00', '2026-01-16 06:30:00'),
(53, 'KEG-2026-010', 'Pelatihan Smart Farming Berbasis IoT untuk Petani Milenial', 'selesai', 'approved', 12, '2026-02-10', '2026-02-12', 'SEAMEO BIOTROP', 'Kota/Kabupaten', 'Pelatihan penerapan sensor IoT untuk pemantauan kelembapan tanah dan irigasi otomatis bagi petani muda di kawasan Bogor.', 'Petani muda memahami dasar integrasi sensor dan sistem irigasi otomatis', 'Tiga kelompok tani berhasil memasang prototipe sistem irigasi otomatis berbasis sensor', 33, 'uploads/kegiatan/kegiatan_43_6a670530717d3.jpg', 1, 10, NULL, '2026-02-10 08:00:00', '2026-02-08 03:00:00', '2026-02-12 06:00:00'),
(54, 'KEG-2026-011', 'Seminar Nasional Restorasi Lahan Gambut', 'selesai', 'approved', 19, '2026-03-05', '2026-03-07', 'Universitas Sriwijaya', 'Nasional', 'Seminar membahas teknik restorasi lahan gambut pasca kebakaran dan strategi pencegahan kebakaran lahan gambut berkelanjutan.', NULL, 'Peserta menyepakati rekomendasi teknis restorasi gambut untuk diusulkan ke pemerintah daerah', 80, 'uploads/kegiatan/kegiatan_43_6a67075642e5b.jpg', 1, 10, NULL, '2026-03-05 09:00:00', '2026-03-03 03:00:00', '2026-03-07 07:00:00'),
(55, 'KEG-2026-012', 'Pelatihan Vertikultur untuk Kelompok Tani Perkotaan', 'selesai', 'approved', 15, '2026-03-25', '2026-03-26', 'SEAMEO BIOTROP', 'Kota/Kabupaten', 'Pelatihan bercocok tanam sayuran secara vertikal untuk memaksimalkan lahan sempit di area perkotaan.', 'Peserta mampu membuat instalasi vertikultur sederhana', 'Peserta membawa pulang unit vertikultur untuk diterapkan di rumah masing-masing', 28, 'uploads/kegiatan/kegiatan_43_6a67076b5af74.jpg', 9, 10, NULL, '2026-03-25 08:00:00', '2026-03-23 03:00:00', '2026-03-26 05:00:00'),
(56, 'KEG-2026-013', 'Workshop Pengolahan Limbah Pertanian Menjadi Kompos', 'selesai', 'approved', 20, '2026-04-08', '2026-04-10', 'Institut Teknologi Bandung', 'Kota/Kabupaten', 'Workshop teknis pengolahan limbah jerami dan sisa panen menjadi kompos berkualitas menggunakan metode fermentasi cepat.', 'Peserta memahami proses fermentasi kompos dalam waktu singkat', 'Dihasilkan modul pelatihan kompos yang siap direplikasi di kelompok tani lain', 42, 'uploads/kegiatan/kegiatan_46_6a72dcf49ea8c.jpg', 1, 10, NULL, '2026-04-08 08:30:00', '2026-04-06 03:00:00', '2026-04-10 06:30:00'),
(57, 'KEG-2026-014', 'Seminar Nasional Pengelolaan DAS Berkelanjutan', 'selesai', 'approved', 10, '2026-04-22', '2026-04-24', 'Universitas Bengkulu', 'Nasional', 'Seminar membahas pendekatan pengelolaan Daerah Aliran Sungai secara terpadu antar sektor untuk mengurangi risiko banjir dan longsor.', NULL, 'Peserta menyusun peta jalan kolaborasi lintas sektor untuk pengelolaan DAS', 65, 'uploads/kegiatan/kegiatan_45_6a72955f15c65.jpg', 1, 10, NULL, '2026-04-22 09:00:00', '2026-04-20 03:00:00', '2026-04-24 07:00:00'),
(58, 'KEG-2026-015', 'Pelatihan Budidaya Anggrek Hutan Tropis', 'selesai', 'approved', 21, '2026-05-12', '2026-05-14', 'Universitas Udayana', 'Kota/Kabupaten', 'Pelatihan teknik budidaya dan pelestarian anggrek spesies asli hutan tropis untuk komunitas pecinta tanaman hias.', 'Peserta memahami teknik perbanyakan anggrek secara vegetatif', 'Komunitas berhasil membudidayakan lima jenis anggrek langka', 25, 'uploads/kegiatan/kegiatan_42_6a5d85e656fbf.jpg', 1, 10, NULL, '2026-05-12 08:00:00', '2026-05-10 03:00:00', '2026-05-14 06:00:00'),
(59, 'KEG-2026-016', 'Seminar Ekowisata dan Konservasi Mangrove', 'selesai', 'approved', 22, '2026-05-27', '2026-05-29', 'Universitas Diponegoro', 'Nasional', 'Seminar membahas pengembangan ekowisata berbasis konservasi mangrove sebagai sumber penghidupan alternatif masyarakat pesisir.', 'Peserta memahami model bisnis ekowisata mangrove berkelanjutan', 'Terumus konsep ekowisata mangrove percontohan untuk tiga desa pesisir', 58, 'uploads/kegiatan/kegiatan_43_6a6705307275b.jpg', 9, 10, NULL, '2026-05-27 09:00:00', '2026-05-25 03:00:00', '2026-05-29 07:00:00'),
(60, 'KEG-2026-017', 'Pelatihan Pengendalian Hama Terpadu (PHT)', 'selesai', 'approved', 12, '2026-06-09', '2026-06-11', 'SEAMEO BIOTROP', 'Kota/Kabupaten', 'Pelatihan pengendalian hama tanaman pangan secara terpadu dengan meminimalkan penggunaan pestisida kimia.', 'Petani mampu mengidentifikasi hama dan menerapkan pengendalian hayati', 'Kelompok tani menerapkan agen hayati sebagai pengendali hama utama', 36, 'uploads/kegiatan/kegiatan_43_6a670530717d3.jpg', 1, 10, NULL, '2026-06-09 08:00:00', '2026-06-07 03:00:00', '2026-06-11 06:00:00'),
(61, 'KEG-2026-018', 'Workshop Digitalisasi Data Pertanian untuk Penyuluh', 'selesai', 'approved', 15, '2026-06-23', '2026-06-24', 'SEAMEO BIOTROP', 'Kota/Kabupaten', 'Workshop penggunaan aplikasi digital untuk pencatatan dan pelaporan data pertanian bagi penyuluh lapangan.', 'Penyuluh mampu menggunakan aplikasi pencatatan data pertanian digital', 'Seluruh penyuluh peserta berhasil migrasi dari pencatatan manual ke digital', 30, 'uploads/kegiatan/kegiatan_43_6a67075642648.jpg', 1, 10, NULL, '2026-06-23 08:30:00', '2026-06-21 03:00:00', '2026-06-24 05:30:00'),
(62, 'KEG-2026-019', 'Seminar Nasional Bioteknologi Pertanian Tropis', 'selesai', 'approved', 23, '2026-07-07', '2026-07-09', 'Universitas Hasanuddin', 'Nasional', 'Seminar nasional membahas pemanfaatan bioteknologi untuk peningkatan produktivitas dan ketahanan tanaman pangan tropis.', NULL, 'Peserta memperoleh wawasan penerapan bioteknologi terkini di sektor pertanian tropis', 95, 'uploads/kegiatan/kegiatan_45_6a72955f15c65.jpg', 1, 10, NULL, '2026-07-07 09:00:00', '2026-07-05 03:00:00', '2026-07-09 07:00:00'),
(63, 'KEG-2026-020', 'Pelatihan Pembibitan Tanaman Kehutanan', 'selesai', 'approved', 14, '2026-07-21', '2026-07-23', 'SEAMEO BIOTROP', 'Kota/Kabupaten', 'Pelatihan teknik pembibitan dan perawatan bibit tanaman kehutanan untuk mendukung program rehabilitasi lahan.', 'Peserta memahami teknik pembibitan bibit unggul tanaman kehutanan', 'Dihasilkan seribu bibit tanaman kehutanan siap tanam dari kegiatan ini', 34, 'uploads/kegiatan/kegiatan_46_6a72dcf49ea8c.jpg', 9, 10, NULL, '2026-07-21 08:00:00', '2026-07-19 03:00:00', '2026-07-23 06:00:00'),
(65, 'KEG-2026-022', 'Workshop Hidroponik NFT untuk Sekolah', 'berlangsung', 'approved', 6, '2026-08-15', '2026-08-20', 'SEAMEO BIOTROP', 'Kota/Kabupaten', 'Workshop instalasi dan perawatan sistem hidroponik NFT sederhana sebagai media pembelajaran sains di sekolah.', 'Guru dan siswa mampu merawat instalasi hidroponik NFT secara mandiri', NULL, 32, 'uploads/kegiatan/kegiatan_47_6a72e29a99f3c.jpg', 1, 10, NULL, '2026-08-15 08:00:00', '2026-08-13 03:00:00', '2026-08-17 06:00:00'),
(66, 'KEG-2026-023', 'Workshop AI untuk Prediksi Hasil Panen', 'belum_berlangsung', 'approved', 13, '2026-08-25', '2026-08-27', 'SEAMEO BIOTROP', 'Kota/Kabupaten', 'Workshop pengenalan model machine learning sederhana untuk memprediksi hasil panen berdasarkan data cuaca dan tanah historis.', 'Peserta memahami dasar penerapan model prediksi hasil panen berbasis data', NULL, NULL, NULL, 9, 4, NULL, '2026-08-20 11:20:40', '2026-08-16 03:00:00', '2026-08-20 04:20:40'),
(67, 'KEG-2026-024', 'Seminar Nasional Ketahanan Pangan Perkotaan', 'belum_berlangsung', 'approved', 12, '2026-09-10', '2026-09-12', 'SEAMEO BIOTROP', 'Nasional', 'Seminar membahas strategi peningkatan ketahanan pangan di wilayah perkotaan melalui optimalisasi lahan terbatas dan rantai pasok pangan lokal.', 'Peserta memahami strategi ketahanan pangan berbasis lahan perkotaan', NULL, NULL, NULL, 1, 10, NULL, '2026-08-17 09:00:00', '2026-08-15 03:00:00', '2026-08-17 09:00:00');
